mapper.select:
SELECT outing_id AS outingId, member_id AS memberId, t0, points_spent AS pointsSpent, zero_point_blocks AS zeroPointBlocks
FROM city_game_outing WHERE board_id = #{boardId} AND t0 <= #{asOf}
ORDER BY member_id, t0, outing_id LIMIT #{limit}

mapper.insert:
INSERT INTO city_point_event(board_id, point_id, component, aggregate_version, availability, merchant_version, platform_version, holder_team_id)
SELECT board_id, point_id, #{component},
       CASE #{component} WHEN 'SLOT' THEN slot_version WHEN 'MERCHANT' THEN merchant_version ELSE platform_version END,
       availability, merchant_version, platform_version, #{holderTeamId}
FROM city_game_point WHERE board_id = #{boardId} AND point_id = #{pointId}
